var WB_CATS={kitchen:["Jiko & qalab","Kitchen & tools"],bathroom:["Musqul & daryeel","Bathroom & care"],cleaning:["Nadiifin & guri","Cleaning & home"],tools:["Qalab & dayactir","Tools & repair"],home_extra:["Guriga gudihiisa","Inside the home"],animals_extra:["Xayawaan","Animals"],vehicles:["Gaadiid & safar","Transport & travel"],baby:["Ilmo & carruur","Baby & children"],school_office:["Dugsi & xafiis","School & office"],sports:["Isboorti & ciyaar","Sport & play"],music_art:["Muusig & farshaxan","Music & art"],food_extra:["Cunto & cabitaan","Food & drink"],nature_extra:["Dabeecad & cimilo","Nature & weather"],body_extra:["Jidhka","The body"],clothes_extra:["Dhar","Clothes"],town_extra:["Magaalo & adeeg","Town & services"],adjectives:["Sifooyin","Describing words"],feelings_adj:["Dareen & dabeecad","Feelings & character"],verbs:["Ficillo: guri & maalin","Verbs: home & daily life"],verbs2:["Ficillo: jidh & shaqo","Verbs: body & work"],phrases:["Weedho faa'iido leh","Useful phrases"]};
function ensureStageF(st){if(!st||typeof st!=="object")return{best:{},wbOpened:false,lastSeen:""};if(!st.stageF||typeof st.stageF!=="object"||Array.isArray(st.stageF))st.stageF={best:{},wbOpened:false,lastSeen:""};if(!st.stageF.best||typeof st.stageF.best!=="object"||Array.isArray(st.stageF.best))st.stageF.best={};if(typeof st.stageF.wbOpened!=="boolean")st.stageF.wbOpened=!!st.stageF.wbOpened;if(typeof st.stageF.lastSeen!=="string")st.stageF.lastSeen="";return st.stageF}
function awardBestXP(key,points){if(typeof guestMode!=="undefined"&&guestMode)return 0;if(!S)return 0;ensureStageF(S);var pts=Math.max(0,Math.round(points||0));var prev=S.stageF.best[key]||0;if(pts<=prev)return 0;S.stageF.best[key]=pts;addActivity(pts-prev,0);return pts-prev}
function srsApplyGrade(c,g){var intervals=[1,3,7,16,35];if(g===0)c.box=0;else if(g===2)c.box=Math.min(4,c.box+2);else c.box=Math.min(4,c.box+1);c.due=Date.now()+intervals[c.box]*86400000;return c.box}
function wordBankCheck(){var seen={},dup=0;WORDBANK.forEach(function(w){var k=norm(w[0]);if(seen[k])dup++;seen[k]=1});var fullSet={};FULLDICT.forEach(function(e){fullSet[norm(e.en)]=1});var overlap=0;WORDBANK.forEach(function(w){if(fullSet[norm(w[0])])overlap++});return{wb:WORDBANK.length,dup:dup,overlap:overlap,lessonEntries:FULLDICT.length,total:FULLDICT.length+WORDBANK.length}}
function sfDialog(titleSo,titleEn,bodySo,bodyEn,okLabel){var old=document.getElementById("sfModal");if(old)old.remove();var d=document.createElement("div");d.className="sfmodal";d.id="sfModal";d.innerHTML='<div class="box" role="dialog" aria-modal="true"><h2 class="u-mt-1 u-mb-1">'+lng(esc(titleSo),esc(titleEn))+'</h2><p>'+esc(bodySo)+'</p><p class="muted">'+esc(bodyEn)+'</p><button class="u-w-full btn" id="sfModalOk">'+esc(okLabel||lng("Waayahay","OK"))+'</button></div>';document.body.appendChild(d);document.getElementById("sfModalOk").addEventListener("click",function(){d.remove()});d.addEventListener("click",function(e){if(e.target===d)d.remove()})}
var wbQuery="",wbShown=60,wbCat="all";
function wbOpenPool(){if(typeof guestMode!=="undefined"&&guestMode)return;ensureStageF(S);if(S.stageF.wbOpened)return;S.stageF.wbOpened=true;var now=Date.now();WORDBANK.forEach(function(w,i){if(!S.srs.some(function(c){return c.en===w[0]}))S.srs.push({en:w[0],so:w[1],box:0,due:now+Math.floor(i/20)*86400000,wb:1})});save()}
function renderWordBank(){
 ensureE();wbOpenPool();
 var q=norm(wbQuery);
 var list=WORDBANK.filter(function(w){if(wbCat!=="all"&&w[4]!==wbCat)return false;if(!q)return true;return norm(w[0]).indexOf(q)>=0||norm(w[1]).indexOf(q)>=0});
 var shown=list.slice(0,wbShown);
 var chk=wordBankCheck();
 var h='<h1>\u{1F5C3}️ Kaydka Ereyada / Word Bank</h1>'+dictModeBar()+
 '<div class="card"><h2>Barnaamijka erayada / The word program — si daacad ah / honestly</h2>'+
 '<p>Kaydkani waa <strong>dufcaddii 1aad (Batch 1)</strong>: <strong>1,000 eray oo cusub</strong> oo maalinle ah, mid kasta oo leh tarjumaad Soomaali, jumlo tusaale ah (Ingiriisi + Soomaali), iyo sawir ama calaamad marka eraygu yahay mid la taaban karo. Dhammaan 1,000 waa la hubiyay inay <strong>aanay</strong> ku jirin 7,900-ka eray ee cashirrada — isku-darka cusub ee la hubiyay waa <strong>'+chk.total+' eray</strong> (7,900 cashir + 1,000 kayd).</p>'+
 '<p class="muted" lang="en">This is <strong>Batch 1</strong>: <strong>1,000 new</strong> everyday words, each with a Somali translation, an example sentence pair (English + Somali), and a picture or tile where the word is concrete. All 1,000 were duplicate-scanned against the 7,900 lesson words — zero overlaps — so the verified new total is <strong>'+chk.total+' words</strong>. The program target is 15,000 words in total, reached in verified batches like this one. This is batch 1, not the finish line.</p>'+
 '<p>Erayada kaydkani waxay ku biiraan <strong>dib-u-eegistaada (SRS)</strong> markaad kaydka furto — 20 eray maalintii ayay soo baxaan si aanay kuugu badnaan. Xusuusnow: xusuusta erayada kaydkani <strong>uma xisaabna</strong> guusha cashirrada (mastery-ga cashirka).</p>'+
 '<p class="muted" lang="en">Word Bank words join your <strong>spaced review (SRS)</strong> as flashcards when you open the Word Bank — they surface 20 a day so they never flood your review. Word-bank recall does <strong>not</strong> count toward lesson mastery.</p></div>'+
 '<div class="u-mt-4 card"><label for="wbQ">'+lng('Raadi eray','Search a word')+'</label><input type="text" id="wbQ" value="'+esc(wbQuery)+'" placeholder="Ingiriisi ama Soomaali / English or Somali">'+
 '<div class="u-row u-wrap u-mt-3 u-mb-3"><button class="chipbtn '+(wbCat==="all"?"sel":"")+'" data-wbcat="all">Dhammaan / All (1,000)</button>'+Object.keys(WB_CATS).map(function(k){return '<button class="chipbtn '+(wbCat===k?"sel":"")+'" data-wbcat="'+k+'">'+esc(WB_CATS[k][0])+' / '+esc(WB_CATS[k][1])+'</button>'}).join("")+'</div>'+
 '<p class="small muted">'+list.length+' '+lng('eray','words')+''+(list.length>wbShown?" — "+wbShown+lng("-ka hore","showing first")+" "+wbShown:"")+'</p>'+
 '<div class="picgrid">'+shown.map(function(w){var v=visualFor(w[0]);var vis=v?visHTML(w[0]):'<span class="visTile" aria-hidden="true">'+esc(w[0].charAt(0).toUpperCase())+'</span>';return '<div class="piccard"><div class="u-mb-2">'+vis+'</div><b lang="en">'+esc(w[0])+'</b><br><span class="muted" lang="so">'+esc(w[1])+'</span><br><span class="small" lang="en">'+esc(w[2])+'</span><br><span class="small muted" lang="so">'+esc(w[3])+'</span><br>'+speakBtn(w[0])+'</div>'}).join("")+'</div>'+
 (list.length>wbShown?'<button class="u-mt-3 btn" id="wbMore">Muuji kuwo kale / Show more (+60)</button>':"")+'</div>';
 app.innerHTML=h;bindSpeak(app);wireDictBar();
 var qi=document.getElementById("wbQ");qi.addEventListener("input",function(){wbQuery=qi.value;wbShown=60;clearTimeout(window.__wq);window.__wq=setTimeout(function(){var pos=qi.selectionStart;renderWordBank();var nq=document.getElementById("wbQ");if(nq){nq.focus();nq.setSelectionRange(pos,pos)}},220)});
 app.querySelectorAll("[data-wbcat]").forEach(function(b){b.addEventListener("click",function(){wbCat=b.dataset.wbcat;wbShown=60;renderWordBank()})});
 var wm=document.getElementById("wbMore");if(wm)wm.addEventListener("click",function(){wbShown+=60;renderWordBank()});
}
